TLM.f("Sancti/03-04cc",{"officium":"S. Lucii I Papæ et Martyris","rule":["vide C2b;","OPapaM=Lúcium;"],"fallback":"Commune/C2b","from":{"Introitus":"Commune/C2b","Lectio":"Commune/C2b","Graduale":"Commune/C2b","Tractus":"Commune/C2b","Evangelium":"Commune/C2b","Offertorium":"Commune/C2b","Communio":"Commune/C2b"},"sections":{"Introitus":[{"k":"ref","la":"Dan 3:84; 3:87"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."},{"k":"ref","la":"Dan 3:57"},{"k":"text","la":"Benedícite, ómnia ópera Dómini, Dómino: laudáte et superexaltáte eum in sǽcula."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."}],"Oratio":[{"k":"text","la":"Gregem tuum, Pastor ætérne, placátus inténde: et, per beátum Lúcium Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 1:3-7"},{"k":"text","la":"Fratres: Benedíctus Deus et Pater Dómini nostri Jesu Christi, Pater misericordiárum, et Deus totíus consolatiónis, qui consolátur nos in omni tribulatióne nostra: ut possímus et ipsi consolári eos, qui in omni pressúra sunt, per exhortatiónem, qua exhortámur et ipsi a Deo. Quóniam sicut abúndant passiónes Christi in nobis: ita et per Christum abúndat consolátio nostra. Sive autem tribulámur pro vestra exhortatióne et salúte, sive consolámur pro vestra consolatióne, sive exhortámur pro vestra exhortatióne et salúte, quæ operátur tolerántiam earúndem passiónum, quas et nos pátimur: ut spes nostra firma sit pro vobis: sciéntes, quod, sicut sócii passiónum estis, sic éritis et consolatiónis: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum."},{"k":"text","la":"Et constituísti eum super ópera mánuum tuárum, Dómine. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hic est Sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum."},{"k":"text","la":"Et constituísti eum super ópera mánuum tuárum, Dómine.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:24-27"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Si quis vult post me veníre, ábneget semetípsum, et tollat crucem suam, et sequátur me. Qui enim voluerit ánimam suam salvam fácere, perdet eam: qui autem perdíderit ánimam suam propter me, invéniet eam. Quid enim prodest hómini, si mundum univérsum lucrétur, ánimæ vero suæ detriméntum patiátur? Aut quam dabit homo commutatiónem pro ánima sua? Fílius enim hóminis ventúrus est in glória Patris sui cum Angelis suis: et tunc reddet unicuíque secúndum ópera ejus."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Oblátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, in cápite ejus corónam de lápide pretióso. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"2a766eabb93192c2":{"t":"<i>Pomolimo se</i>.\nVječni Pastiru, milosno pazi svoje stado i čuvaj vječnom zaštitom po zagovoru blaženoga Lucija, tvoga mučenika i pape koga si postavio za pastira čitave Crkve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"465033a1b349c3e4":{"t":"Po prikaznim darovima, molimo, Gospodine, dobrostivo rasvijetli svoju Crkvu da i stado tvoje sve više i više napreduje i da ti ugode pastiri koje si postavio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"48b397156b3ff99b":{"t":"<i>Pomolimo se</i>.\nVladaj, molimo, Gospodine, svojom Crkvom koja je nahranjena, na svetoj gozbi, da po tvome snažnom ravnanju zadobije porast slobode i ustraje u savršenom bogoštovlju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
